import {jsPDF} from 'jspdf';

export function closurePdf({closure,management,period,now,logo,issuer,issuerRole,demo=false}) {
  if(!closure.eligible) throw Error('La gerencia todavía tiene remisiones pendientes de conciliación.');
  const names=[issuer?.trim()].filter(Boolean);
  if(!names.length)throw Error('Falta la descripción del usuario que emite el documento.');
  const files=[...new Set(closure.remissions.map(r=>r.expediente?.trim()).filter(Boolean))];
  if(closure.remissions.some(r=>!r.expediente?.trim())) throw Error('Falta el número de expediente de una remisión.');
  const zone=management.name.replace(/^Gerencia\s+/i,'');
  const month=new Intl.DateTimeFormat('es-PY',{month:'long',timeZone:'UTC'}).format(new Date(Date.UTC(period.year,period.month-1,1)));
  const date=new Intl.DateTimeFormat('es-PY',{day:'numeric',month:'long',year:'numeric',timeZone:'America/Asuncion'}).format(now);
  const pdf=new jsPDF({unit:'mm',format:'a4'}), left=30,width=150;
  pdf.addImage(logo,'PNG',30,22,150,17.06);
  pdf.setFont('helvetica','bold');pdf.setFontSize(10);
  let y=48;
  const heading=pdf.splitTextToSize(`Corresponde ${files.length===1?'al expediente':'a los expedientes'} N.º ${files.join(' / ')}`,width);
  for(const line of heading){if(y>265){pdf.addPage();y=30;}pdf.text(line,left,y);y+=5;}y+=7;
  pdf.setFont('helvetica','normal');pdf.text(`Asunción, ${date}`,180,y,{align:'right'});y+=12;
  const paragraphs=[
    `A la Dirección de Operaciones, se informa que se ha realizado la verificación integral de las documentaciones correspondientes a la ${period.half===1?'primera':'segunda'} quincena del mes de ${month}/${period.year}, remitidas por la Gerencia Departamental de Servicios Zona ${zone}.`,
    'Las mismas corresponden a operaciones de Alta cliente | Desembolso | Cobranza, reflejadas en el sistema de cartera de préstamos de los distintos CAC que componen esta Gerencia.',
    'Se hace constar que en el control realizado no se registran documentos faltantes, y los adjuntos se encuentran dentro de lo establecido en el “Manual de Procedimientos de Rendición de Documentos que respaldan las Operaciones de Desembolsos de Préstamos”, aprobado por la Resolución del Consejo Directivo N.º 26, Acta N.º 34 de fecha 23/10/2025.',
    'Por lo expuesto se da por finalizado el proceso de verificación documental, para proseguir con los trámites.'
  ];
  for(const p of paragraphs){const lines=pdf.splitTextToSize(p,width);for(const [index,line] of lines.entries()){if(y>265){pdf.addPage();y=30;}const words=line.trim().split(/\s+/);if(index<lines.length-1&&words.length>1){const gap=(width-words.reduce((sum,word)=>sum+pdf.getTextWidth(word),0))/(words.length-1);let x=left;for(const word of words){pdf.text(word,x,y);x+=pdf.getTextWidth(word)+gap;}}else{pdf.text(line,left,y);}y+=5.82;}y+=7;}
  const signature=pdf.splitTextToSize(names.join(' / '),width);
  if(y+signature.length*5+27>270) pdf.addPage(),y=35;
  y+=14;pdf.setFont('helvetica','bold');pdf.text(signature,105,y,{align:'center'});y+=signature.length*5+2;
  pdf.setFont('helvetica','normal');pdf.text(issuerRole==='technical'?'Dirección de Operaciones':'Unidad de Operaciones',105,y,{align:'center'});
  for(let p=1;p<=pdf.getNumberOfPages();p++){pdf.setPage(p);pdf.setDrawColor(150);pdf.line(30,282,180,282);if(demo){pdf.setFontSize(8);pdf.setTextColor(120);pdf.text('DEMOSTRACIÓN · DATOS FICTICIOS · SIN VALIDEZ INSTITUCIONAL',105,288,{align:'center'});}}
  return pdf;
}

const logo = 'data:image/png;base64,';
export function downloadClosure(data) { const pdf=closurePdf({...data,logo,now:new Date(),demo:false}); pdf.save(closureFilename(data)); }

export function closureFilename({management,period}) {
  const gerencia=management.name.trim().replace(/^Gerencia\s+/i,'').replace(/[<>:"/\\|?*\x00-\x1f]/g,'').replace(/\s+/g,'_');
  const quincena=period.half===1?'Primera_quincena':'Segunda_quincena';
  return `Verificación_doc_GDSZ_${gerencia}_${quincena}_${String(period.month).padStart(2,'0')}-${period.year}.pdf`;
}
